this.supabase
            .channel('agent-tasks')
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'tasks',
                    filter: `org_id=eq.${this.orgId}`,
                },
                (payload: any) => this.handleNewTask(payload.new)
            )
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'tasks',
                    filter: `org_id=eq.${this.orgId}`,
                },
                (payload: any) => {
                    if (payload.new.status === 'retrying') {
                        this.scheduleRetry(payload.new);
                    }
                }
            )
            .subscribe
